L=np.log(P)
cols={}
for k in [-2,-1,0,1,2,3]:
    cols[f'P^{k}']=P**k
    cols[f'tP^{k}']=t*P**k
for k in [-1,0,1,2,3]:
    cols[f'L P^{k}']=L*P**k
    cols[f'tL P^{k}']=t*L*P**k
for k in [-1,0,1,2]:
    cols[f'L2 P^{k}']=L**2*P**k
    cols[f't2 P^{k}']=t**2*P**k
names=list(cols)
A=np.column_stack([cols[n] for n in names])
c,_,_,_=np.linalg.lstsq(A,dP_dt,rcond=None)
r=dP_dt-A@c
print(np.mean(r**2)/np.var(dP_dt))
for n,v in zip(names,c):
